package cn.migi.reader;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.graphics.Bitmap;
import android.provider.DocumentsContract;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;

/** Network/API + writable SAF + native Activity integration, confined to QA package. */
public final class OnlineChecks extends Instrumentation {
    int passed=0;String base;void check(boolean value,String label){if(!value)throw new AssertionError(label);passed++;Bundle b=new Bundle();b.putString("stream","PASS: "+label+"\n");sendStatus(0,b);}
    void waitFor(java.util.function.BooleanSupplier condition)throws Exception{long end=SystemClock.elapsedRealtime()+20000;while(SystemClock.elapsedRealtime()<end){final boolean[] ok={false};runOnMainSync(()->ok[0]=condition.getAsBoolean());if(ok[0])return;Thread.sleep(100);}throw new AssertionError("UI wait timed out");}
    public void onCreate(Bundle args){super.onCreate(args);base=args==null?"http://10.0.2.2:18951":args.getString("base","http://10.0.2.2:18951");start();}
    public void onStart(){Bundle result=new Bundle();try{
        if(!getTargetContext().getPackageName().equals("cn.yukina.online.qa"))throw new AssertionError("QA package only");
        Store store=new Store(getTargetContext());Online online=new Online(getTargetContext(),store);Online.instance=online;for(int i=0;i<online.sources().length();i++)online.sources().getJSONObject(i).put("enabled",false);store.save();
        JSONObject source=new JSONObject().put("id","fixture").put("name","合成在线书源").put("type","catalog").put("base_url",base+"/catalog.json").put("enabled",true);online.putSource(source);
        Online.Result search=online.search(source,"雪色",1);check(search.books.length()==1&&!search.more,"catalog search and Chinese title");
        JSONArray chapters=online.chapters(source,"demo");check(chapters.length()==2,"catalog chapter list");JSONObject entry=online.add(source,search.books.getJSONObject(0),chapters);JSONObject volume=entry.getJSONArray("volumes").getJSONObject(0);check(volume.getString("uri").startsWith("online://fixture/"),"stable source/book/chapter identity");
        volume.put("page",2).put("status","已读").put("seconds",17);online.add(source,search.books.getJSONObject(0),chapters);check(store.books().length()==1&&entry.getJSONArray("volumes").getJSONObject(0).getInt("page")==2&&volume.getInt("seconds")==17,"duplicate import and refresh preserve progress/time/status");
        for(String kind:new String[]{"mangadex","komga","suwayomi"}){JSONObject s=new JSONObject(source.toString()).put("type",kind).put("base_url",base).put("source_id","1234567890123456789");Online.Result r=online.search(s,"雪色",1);check(r.books.length()==1,kind+" search API");JSONArray c=online.chapters(s,"demo");check(c.length()==1,kind+" chapter API");JSONObject meta=new JSONObject().put("book_id","demo").put("chapter",c.getJSONObject(0));check(online.pages(s,meta).size()==4,kind+" page API");}
        Books.Engine engine=Books.open(getTargetContext().getContentResolver(),volume);check(engine.count()==4,"online engine count");Bitmap image=engine.render(0,600);check(image.getWidth()==800&&image.getHeight()==1100,"smooth preset avoids enlarging small source pages");image.recycle();engine.close();check(store.settings().getJSONArray("onlineCacheRoots").length()==0,"online reading creates no download cache");
        check(online.pageMemory.used>0,"chapter close retains bounded compressed RAM pages");store.settings().put("onlineQuality","original");Books.Engine originalEngine=Books.open(getTargetContext().getContentResolver(),volume);Bitmap originalImage=originalEngine.render(0,600);check(originalImage.getWidth()==800&&originalImage.getHeight()==1100&&originalImage.getPixel(0,0)==android.graphics.Color.parseColor("#d6e9df"),"original preset preserves full dimensions and exact source color");originalImage.recycle();originalEngine.close();store.settings().put("onlineQuality","smooth");
        Bitmap generated=Bitmap.createBitmap(2400,3600,Bitmap.Config.ARGB_8888);generated.eraseColor(android.graphics.Color.WHITE);java.io.ByteArrayOutputStream encoded=new java.io.ByteArrayOutputStream();generated.compress(Bitmap.CompressFormat.PNG,100,encoded);generated.recycle();byte[] raw=encoded.toByteArray();check(OnlineQuality.prepare(raw,"original")==raw,"original quality bytes are never recompressed");for(String quality:new String[]{"low","smooth"}){byte[] prepared=OnlineQuality.prepare(raw,quality);Bitmap converted=OnlineQuality.decode(prepared,"original");check(Math.max(converted.getWidth(),converted.getHeight())==(quality.equals("low")?1280:2000),quality+" adaptive edge limit applied");converted.recycle();}

        Uri tree=DocumentsContract.buildTreeDocumentUri(getContext().getPackageName()+".onlinefiles","root");online.selectCache(tree);check(store.settings().getJSONArray("onlineCacheRoots").length()==1,"SAF independent download directory");
        AtomicBoolean cancel=new AtomicBoolean();boolean cancelled=false;try{online.download(volume,cancel,(title,page,total)->{if(page==2)cancel.set(true);});}catch(IOException expected){cancelled=true;}check(cancelled&&online.cached(volume,true)==null,"partial download not marked complete");check(online.cached(volume,false)!=null,"partial manifest persisted");cancel.set(false);online.download(volume,cancel,(t,p,total)->{});check(online.cached(volume,true)!=null,"resumable download completes");
        source.put("enabled",false);online.putSource(source);engine=Books.open(getTargetContext().getContentResolver(),volume);image=engine.render(3,600);check(!image.isRecycled(),"offline read with source disabled");image.recycle();engine.close();source.put("enabled",true);online.putSource(source);
        Online.Cached cached=online.cached(volume,true);cached.folder.find("000001.img").write("damaged".getBytes("UTF-8"));boolean corrupt=false;try{online.cachedPage(cached,0);}catch(IOException expected){corrupt=true;}check(corrupt,"cached page hash detects damage");online.download(volume,cancel,(t,p,total)->{});check(online.cachedPage(online.cached(volume,true),0).length>100,"redownload repairs damaged page");
        int count=online.sources().length();boolean invalid=false;try{online.importSources("{\"sources\":[{\"type\":\"script\",\"base_url\":\"file:///x\"}]}");}catch(Exception expected){invalid=true;}check(invalid&&online.sources().length()==count,"invalid source package rejected atomically");store.save();
        Intent intent=new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);MainActivity activity=(MainActivity)startActivitySync(intent);waitFor(()->activity.store!=null&&activity.root.getWidth()>0);JSONObject active=activity.store.find(entry.getString("id"));runOnMainSync(()->activity.openBook(active,0));waitFor(()->activity.engine!=null&&!activity.busy&&activity.surface!=null);check(activity.screen==MainActivity.READER,"native online/offline reader integration");check(activity.owner.optString("id").equals(entry.getString("id")),"same unified shelf owner for online chapters");
        runOnMainSync(()->activity.center());check(activity.screen==MainActivity.READER&&activity.controls,"immersive overlay remains in reading mode");runOnMainSync(()->activity.showDetail(active));check(activity.screen==MainActivity.DETAIL,"online title uses native detail/status screen");
        runOnMainSync(()->activity.onlineUi.show());check(activity.screen==OnlineUi.SCREEN,"native source discovery page");runOnMainSync(()->{activity.onlineUi.query="雪色";activity.onlineUi.search();});waitFor(()->activity.onlineUi.results.length()==1);check(activity.onlineUi.results.length()==1,"native async source search");
        runOnMainSync(()->activity.onlineUi.downloads());check(activity.screen==OnlineUi.CACHE,"native cache-management page");
        JSONArray jobs=new JSONArray().put(active.getJSONArray("volumes").getJSONObject(1));OnlineDownloadService.saveQueue(activity,jobs);runOnMainSync(()->activity.startForegroundService(new Intent(activity,OnlineDownloadService.class).putExtra("scope",active.optString("uri"))));waitFor(()->OnlineDownloadService.message.contains("下载完成")&&!OnlineDownloadService.running);check(OnlineDownloadService.loadQueue(activity).length()==0,"foreground queue persisted and completed");check(activity.onlineUi.online.cached(active.getJSONArray("volumes").getJSONObject(1),true)!=null,"foreground service wrote verified SAF chapter");
        online.clearCache(volume);check(online.cached(volume,true)==null,"explicit cleanup removes generated pages only");check(store.books().length()==1&&volume.optInt("page")==2,"cache cleanup preserves shelf/progress");runOnMainSync(()->activity.finish());
        result.putString("stream","Online Android checks passed: "+passed+"\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable e){result.putString("stream","FAILED after "+passed+": "+e+"\n"+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
